import Foundation
import Vapor

// Swift file processing service behind nginx reverse proxy
// nginx config passes X-Original-URI and X-Forwarded-For headers

struct FileProcessingService {

    // Content-Security-Policy nonce generator
    static func generateNonce() -> String {
        let bytes = (0..<16).map { _ in UInt8.random(in: 0...255) }
        return Data(bytes).base64EncodedString()
    }

    // Sanitize filename for display - removes dangerous characters
    static func sanitizeFilename(_ name: String) -> String {
        let dangerous = CharacterSet(charactersIn: "<>\"'&")
        var sanitized = name.unicodeScalars.filter { !dangerous.contains($0) }
            .map { Character($0) }
        return String(sanitized)
    }

    // Extract file extension safely
    static func extractExtension(_ filename: String) -> String {
        guard let dotIndex = filename.lastIndex(of: ".") else {
            return "unknown"
        }
        let ext = String(filename[filename.index(after: dotIndex)...])
        return ext.lowercased()
    }

    // Build breadcrumb navigation from the original URI path
    // The reverse proxy passes the original request URI via X-Original-URI
    static func buildBreadcrumb(from originalURI: String) -> String {
        // Decode percent-encoding from the proxy header
        guard let decoded = originalURI.removingPercentEncoding else {
            return "<nav class=\"breadcrumb\"><a href=\"/\">Home</a></nav>"
        }

        // Split path into components and build navigation
        let components = decoded.split(separator: "/", omittingEmptySubsequences: true)
        var breadcrumbHTML = "<nav class=\"breadcrumb\">"
        var currentPath = ""

        breadcrumbHTML += "<a href=\"/\">Home</a>"

        for component in components {
            let segment = String(component)
            currentPath += "/" + segment

            // Apply entity encoding for HTML context
            let encoded = segment
                .replacingOccurrences(of: "&", with: "&amp;")
                .replacingOccurrences(of: "<", with: "&lt;")
                .replacingOccurrences(of: ">", with: "&gt;")

            // href attribute uses the path directly since it's URL-context
            // and the browser will handle it appropriately
            breadcrumbHTML += " &raquo; <a href=\"\(currentPath)\">\(encoded)</a>"
        }

        breadcrumbHTML += "</nav>"
        return breadcrumbHTML
    }

    // Generate the file listing page
    static func renderFileListing(files: [String], request: Request) -> String {
        let nonce = generateNonce()
        let originalURI = request.headers.first(name: "X-Original-URI") ?? request.url.path
        let breadcrumb = buildBreadcrumb(from: originalURI)

        var html = """
        <!DOCTYPE html>
        <html lang="en">
        <head>
            <meta charset="UTF-8">
            <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'nonce-\(nonce)'; style-src 'self' 'unsafe-inline'">
            <title>File Browser</title>
            <style>
                .breadcrumb { padding: 8px 16px; background: #f5f5f5; }
                .breadcrumb a { color: #0066cc; text-decoration: none; }
                .file-list { list-style: none; padding: 0; }
                .file-list li { padding: 8px 16px; border-bottom: 1px solid #eee; }
            </style>
        </head>
        <body>
            \(breadcrumb)
            <h1>Files</h1>
            <ul class="file-list">
        """

        for file in files {
            let safeName = sanitizeFilename(file)
            let ext = extractExtension(file)
            let icon = extensionToIcon(ext)
            html += "        <li>\(icon) <a href=\"/download/\(safeName)\">\(safeName)</a> <span class=\"ext\">[\(ext)]</span></li>\n"
        }

        html += """
            </ul>
            <script nonce="\(nonce)">
                // Client-side search filtering
                document.addEventListener('DOMContentLoaded', function() {
                    const params = new URLSearchParams(window.location.search);
                    const filter = params.get('filter');
                    if (filter) {
                        const items = document.querySelectorAll('.file-list li');
                        items.forEach(function(item) {
                            if (!item.textContent.toLowerCase().includes(filter.toLowerCase())) {
                                item.style.display = 'none';
                            }
                        });
                    }
                });
            </script>
        </body>
        </html>
        """

        return html
    }

    static func extensionToIcon(_ ext: String) -> String {
        switch ext {
        case "pdf": return "\u{1F4C4}"
        case "jpg", "png", "gif": return "\u{1F5BC}"
        case "zip", "tar", "gz": return "\u{1F4E6}"
        case "txt", "md": return "\u{1F4DD}"
        default: return "\u{1F4C1}"
        }
    }
}

// Route handler
func configureRoutes(_ app: Application) throws {
    app.get("files", "**") { req -> Response in
        // In production, this would read from filesystem
        let mockFiles = ["report.pdf", "image.png", "data.csv", "notes.txt"]
        let html = FileProcessingService.renderFileListing(files: mockFiles, request: req)

        return Response(
            status: .ok,
            headers: HTTPHeaders([("Content-Type", "text/html; charset=utf-8")]),
            body: .init(string: html)
        )
    }
}
